import React from "react";
import doctorImage from "../../../assets/images/users-vector-icon-png_260862.jpg";

const doctors = [
  {
    name: "Dr. Calvin Carlo",
    specialty: "Eye Care",
    experience: "3 Years Experienced",
    image:
      "	https://doctris-admin.vercel.app/static/media/01.d8b9651b2a3ba6336221.jpg", // Replace with actual image URL
  },
  {
    name: "Dr. Cristino Murphy",
    specialty: "Gynecology",
    experience: "5 Years Experienced",
    image:
      "https://doctris-admin.vercel.app/static/media/02.38e00cf46dc0cbd9fed3.jpg", // Replace with actual image URL
  },
  {
    name: "Dr. Alia Reddy",
    specialty: "Psychotherapy",
    experience: "4 Years Experienced",
    image:
      "	https://doctris-admin.vercel.app/static/media/03.b192aca452235f61b392.jpg", // Replace with actual image URL
  },
  {
    name: "Dr. Toni Kovar",
    specialty: "Orthopedic",
    experience: "6 Years Experienced",
    image:
      "	https://doctris-admin.vercel.app/static/media/04.f645789423636f851180.jpg", // Replace with actual image URL
  },
];

const DoctorCard = ({ name, specialty, experience, image }) => {
  return (
    <div className="flex items-center space-x-4 p-1 bg-gray-50 rounded-lg shadow-md mb-4">
      <img
        src={image}
        alt={name}
        className="w-20 h-20 rounded-full object-cover"
      />
      <div>
        <h3 className="text-lg font-semibold text-gray-900">{name}</h3>
        <p className="text-sm text-gray-600">{specialty}</p>
        <p className="text-sm text-gray-500">{experience}</p>
      </div>
    </div>
  );
};

const DoctorsList = () => {
  return (
    <div className=" bg-gray-50 p-5 rounded-lg shadow-lg w-[30%] h-auto">
      <h2 className="text-xl font-bold mb-6 text-gray-800">Doctors List</h2>
      <div className="space-y-5">
        {doctors.map((doctor, index) => (
          <DoctorCard
            key={index}
            name={doctor.name}
            specialty={doctor.specialty}
            experience={doctor.experience}
            image={doctor.image}
          />
        ))}
      </div>
    </div>
  );
};

export default DoctorsList;
